class Tier:
    def __init__(self, name):
        self.name = name

    def vorstellen(self):
        print(f"Ich bin {self.name}.")

class Hund(Tier):          # Hund erbt von Tier
    def bellen(self):
        print("Wuff!")

h = Hund("Bello")
h.vorstellen()   # Ich bin Bello.  (geerbt)
h.bellen()       # Wuff!           (neu)

class Tier:
    def __init__(self, name):
        self.name = name

    def laut(self):
        return "..."

class Katze(Tier):
    def laut(self):
        return "Miau"

class Kuh(Tier):
    def laut(self):
        return "Muh"

for t in [Katze("Minka"), Kuh("Berta"), Tier("Unbekannt")]:
    print(t.name, "sagt", t.laut())

class Fahrzeug:
    def __init__(self, marke, ps):
        self.marke = marke
        self.ps = ps

    def beschreibung(self):
        return f"{self.marke} mit {self.ps} PS"

class Elektroauto(Fahrzeug):
    def __init__(self, marke, ps, akku_kwh):
        super().__init__(marke, ps)    # Basisklasse erledigt marke und ps
        self.akku_kwh = akku_kwh

    def beschreibung(self):
        basis = super().beschreibung() # geerbte Methode weiterverwenden
        return f"{basis}, Akku {self.akku_kwh} kWh"

e = Elektroauto("Tesla", 300, 75)
print(e.beschreibung())   # Tesla mit 300 PS, Akku 75 kWh

class Fahrrad(Fahrzeug):
    def __init__(self, marke, gaenge):
        self.gaenge = gaenge     # super().__init__ fehlt!

f = Fahrrad("KTM", 21)
print(f.marke)   # AttributeError: 'Fahrrad' object has no attribute 'marke'

