class Person:
    def __init__(self, name):
        self.name = name

    def info(self):
        return self.name

class Lehrer(Person):
    def info(self):
        return super().info() + " (Lehrer)"

print(Lehrer("Huber").info())

class Form:
    def __init__(self, farbe):
        self.farbe = farbe

class Kreis(Form):
    def __init__(self, farbe, radius):
        self.radius = radius

k = Kreis("rot", 2)
print(k.farbe)
